export async function listMyApplications(req, res) { const rows = await query('SELECT a.*,i.title,i.company_name,i.location,i.registration_fee FROM internship_applications a JOIN internships i ON i.id=a.internship_id WHERE a.user_id=? ORDER BY a.applied_at DESC', [req.user.id]); res.json({ success: true, data: rows }); }
